/* VNMY — встроенные вселенные и новеллы для открытия с диска (file://).
 * Не правим руками: npm run build
 */
window.__VNMY_BUILTIN_LIBRARY__ = {"schema":2,"universes":[{"schema":1,"id":"silent-rails","title":"Тихие пути","author":"VNMY demo","description":"Ночные платформы, поздние поезда и разговоры, которые случаются, когда все уже дома.","cover":"cover.webp","accent":"#8fb8d8","order":1,"baseUrl":"","novels":[{"schema":1,"id":"story_last_train","title":"Последний поезд","author":"VNMY demo","description":"Ночь, дождь, отменённый поезд — и девушка, которая тоже никуда не спешит. Короткая история о случайном разговоре.","cover":"assets/bg-platform-night.webp","accent":"#e0b072","universe":"silent-rails","characters":[{"id":"anya","name":"Аня","color":"#e8c08a","sprites":{"neutral":"assets/anya-neutral.webp","smile":"assets/anya-smile.webp"}},{"id":"mark","name":"Марк","color":"#a8c4d8","sprites":{"neutral":"assets/mark-neutral.webp","smile":"assets/mark-smile.webp"}}],"scenes":[{"id":"sc_platform","name":"Платформа","bg":"assets/bg-platform-night.webp","weather":"rain","cast":[{"char":"anya","sprite":"neutral","pos":"center"}],"steps":[{"id":"t1","speaker":null,"text":"02:14. Дождь идёт ровно, как метроном. Последний поезд отменили полчаса назад."},{"id":"t2","speaker":null,"text":"Я остался из упрямства. И ещё потому, что девушка под фонарём тоже не уходила."},{"id":"t3","speaker":"anya","text":"Вы тоже ждёте поезд, которого не будет?"},{"id":"t4","speaker":null,"text":"","choices":[{"text":"«Вообще-то я просто не хочу домой»","goto":"sc_platform:t5"},{"text":"«Да. Из принципа»","goto":"sc_platform:t7"}]},{"id":"t5","speaker":"anya","spriteOverride":"smile","text":"О. Это лучший ответ из всех, что я слышала за сегодня.","mood":"blush","set":[{"var":"sympathy","op":"add","value":1}]},{"id":"t6","speaker":null,"text":"Она улыбнулась так, будто мы уже были знакомы. И кивнула на пустые пути.","goto":"sc_platform:t9"},{"id":"t7","speaker":"anya","text":"Из принципа — это по-нашему."},{"id":"t8","speaker":null,"text":"Она поправила стакан с кофе и не стала спрашивать больше ничего.","goto":"sc_platform:t9"},{"id":"t9","speaker":"anya","text":"Меня зовут Аня. Если поезда нет, можно хотя бы придумать, куда он ехал."},{"id":"t10","speaker":null,"text":"","choices":[{"text":"«В город, где всегда три часа ночи»","goto":"sc_platform:t11"},{"text":"«К морю, чтобы дождь стал волнами»","goto":"sc_platform:t13"}]},{"id":"t11","speaker":"anya","spriteOverride":"smile","text":"Тогда нам точно по пути. У меня там как раз нет ни одной причины оставаться.","set":[{"var":"sympathy","op":"add","value":1}]},{"id":"t12","speaker":null,"text":"Мы придумали расписание. Оно было лучше настоящего.","goto":"sc_platform:t14"},{"id":"t13","speaker":"anya","spriteOverride":"smile","text":"Море. Да. Тогда дождь — это просто волны, которые забыли уйти.","mood":"zoom","set":[{"var":"sympathy","op":"add","value":1}]},{"id":"t14","speaker":null,"text":"Где-то далеко загудело. Поезд всё-таки шёл — пустой и тёплый, будто его отправили специально за нами.","goto":"sc_train:t1"}]},{"id":"sc_train","name":"Вагон","bg":"assets/bg-train.webp","weather":"none","cast":[{"char":"mark","sprite":"neutral","pos":"left","scale":0.94},{"char":"anya","sprite":"smile","pos":"right","scale":0.94}],"steps":[{"id":"t1","speaker":null,"text":"В вагоне было тепло и пусто. Только парень у окна: наушники, стакан чая и вид человека, который едет домой третьи сутки."},{"id":"t2","speaker":"mark","text":"Предупреждаю сразу: я не проверяю билеты и не хочу знакомиться."},{"id":"t3","speaker":"anya","text":"Поздно. Мы уже.","mood":"shake"},{"id":"t4","speaker":"mark","spriteOverride":"smile","text":"Ладно. Тогда я Марк. И термос я вам всё равно не отдам."},{"id":"t9","speaker":"mark","spriteOverride":"smile","if":"sympathy >= 2","text":"Вы знакомы час, а смотритесь как люди с общей историей. Я, пожалуй, пересяду."},{"id":"t5","speaker":null,"text":"Дождь стучал по стеклу. Аня рисовала на запотевшем окне город, которого не было на картах."},{"id":"t6","speaker":"anya","text":"Марк, а ты куда едешь?"},{"id":"t7","speaker":"mark","text":"Домой. Уже третью ночь подряд."},{"id":"t8","speaker":null,"text":"Он сказал это так, что стало ясно: дома его никто не ждёт. Аня не стала уточнять. Просто подвинулась и освободила место у окна.","pause":300,"goto":"sc_kitchen:t1"}]},{"id":"sc_kitchen","name":"Кухня","bg":"assets/bg-kitchen.webp","weather":"rain","cast":[{"char":"anya","sprite":"smile","pos":"center","scale":0.96}],"steps":[{"id":"t1","speaker":null,"text":"Через месяц я стоял на её кухне и ждал, когда закипит чайник. За окном шёл тот же дождь — как будто мы его так и не выключили."},{"id":"t2","speaker":"anya","text":"Ты помнишь, что мы обещали друг другу в том поезде?"},{"id":"t3","speaker":null,"text":"","choices":[{"text":"«Что будем придумывать города»","goto":"sc_kitchen:t4"},{"text":"«Что больше не будем ждать поездов»","goto":"sc_kitchen:t6"},{"text":"«Что ты больше не одна»","goto":"sc_kitchen:t9","if":"sympathy >= 2"}]},{"id":"t4","speaker":"anya","spriteOverride":"neutral","text":"Правильно. Так вот: я нашла ещё один. Он называется никак — его ещё не построили."},{"id":"t5","speaker":null,"text":"Она поставила передо мной чашку. На ней не было ничего написано, и это было самое честное, что я держал в руках за год.","goto":"sc_kitchen:t8"},{"id":"t6","speaker":"anya","spriteOverride":"neutral","text":"Я тоже так думала. Потом поняла: ждать поездов — это и есть наш город."},{"id":"t7","speaker":null,"text":"Чайник щёлкнул. В окне отражались два человека, которые ещё не решили, кем будут друг другу.","goto":"sc_kitchen:t8"},{"id":"t8","speaker":"anya","spriteOverride":"smile","text":"Пойдём на платформу? Сегодня обещали дождь до утра.","goto":"sc_dawn:t1","gotoIf":[{"when":"sympathy >= 3","goto":"sc_dawn:t9"}]},{"id":"t9","speaker":"anya","spriteOverride":"smile","text":"Это ты придумал только что. Значит, тоже считается.","set":[{"var":"sympathy","op":"add","value":1}],"goto":"sc_kitchen:t8"}]},{"id":"sc_dawn","name":"Рассвет","bg":"assets/bg-dawn.webp","weather":"petals","cast":[{"char":"anya","sprite":"smile","pos":"center"}],"steps":[{"id":"t1","speaker":null,"text":"Рассвет был мокрым и розовым. Поезд пришёл точно по расписанию — впервые за всё время."},{"id":"t2","speaker":"anya","text":"Ну вот. И что теперь?"},{"id":"t3","speaker":null,"text":"","choices":[{"text":"Взять её за руку","goto":"sc_dawn:t4"},{"text":"Отпустить и уехать","goto":"sc_dawn:t6"}]},{"id":"t4","speaker":null,"text":"Ладонь у неё была холодная, как поручень в тамбуре. Никто из нас не отпустил.","mood":"flash","set":[{"var":"took_hand","op":"set","value":true}]},{"id":"t8","if":"sympathy >= 2","text":"За вечер я насчитал {sympathy} поводов остаться. Все они были здесь, в этой руке."},{"id":"t5","speaker":"anya","text":"Значит, едем. В город, которого нет. — И улыбнулась, как тогда, под фонарём.","end":true,"endTitle":"КОНЕЦ · Тот же поезд"},{"id":"t6","speaker":null,"text":"Я сел в вагон и смотрел, как она уменьшается в окне. Она не махала — просто стояла, будто знала, что мы ещё встретимся."},{"id":"t7","speaker":"anya","text":"До следующего дождя.","end":true,"endTitle":"КОНЕЦ · До следующего дождя"},{"id":"t9","text":"Мы дошли до платформы молча — так, как умеют только те, кому уже нечего объяснять.","goto":"sc_dawn:t1"}]}],"vars":[{"name":"sympathy","type":"number","initial":0},{"name":"took_hand","type":"bool","initial":false}],"baseUrl":"stories/silent-rails/novels/last-train/","_builtin":"silent-rails/novels/last-train"}]},{"schema":1,"id":"tyumen","title":"Тюмень","author":"VNMY","description":"Наш мир, наш город: Мельникайте, Тура, Мост влюблённых, Верхний Бор. Истории про людей, которые оказались здесь — и про тех, кто решил остаться.","accent":"#e0a86a","order":2,"baseUrl":"","novels":[{"schema":1,"id":"story_peresylka","title":"Пересылка","author":"VNMY","description":"Бабушкина квартира на Мельникайте оказалась не квартирой, а пересылкой — местом, где застревают те, кто был между мирами. Одна ночь, шесть девчонок из чужих миров, один холодильник и первая неделя, за которую надо как-то научиться жить вместе.","accent":"#e0a86a","universe":"tyumen","vars":[{"name":"имя","type":"text","initial":""},{"name":"вахта","type":"number","initial":0},{"name":"близость_гвен","type":"number","initial":0},{"name":"близость_сакура","type":"number","initial":0},{"name":"близость_микаса","type":"number","initial":0},{"name":"близость_тентен","type":"number","initial":0},{"name":"близость_энни","type":"number","initial":0},{"name":"близость_фелиция","type":"number","initial":0},{"name":"порог_гвен","type":"bool","initial":false},{"name":"порог_сакура","type":"bool","initial":false},{"name":"порог_микаса","type":"bool","initial":false},{"name":"порог_тентен","type":"bool","initial":false},{"name":"порог_энни","type":"bool","initial":false},{"name":"порог_фелиция","type":"bool","initial":false}],"characters":[{"id":"hero","name":"{имя}","color":"#e0a86a"},{"id":"gwen","name":"Гвен","color":"#f2a0c0"},{"id":"sakura","name":"Сакура","color":"#f0a878"},{"id":"mikasa","name":"Микаса","color":"#b8c4d6"},{"id":"tenten","name":"Тентен","color":"#d8a25e"},{"id":"annie","name":"Энни","color":"#9fb8cc"},{"id":"felicia","name":"Фелиция","color":"#b998e0"}],"scenes":[{"id":"sc_door","name":"Ночь первая","cast":[],"steps":[{"id":"t1","text":"Ключ повернулся с третьего раза. Как будто квартира сначала решила, что я не тот."},{"id":"t2","text":"Бабушка умерла в апреле. Квартиру на Мельникайте я получил в июле. Приехал в октябре — потому что октябрь в Тюмени умеет делать вид, что ты никуда не опаздывал."},{"id":"t3","ask":{"var":"имя","label":"Как тебя зовут?","placeholder":"имя","value":"Гость"}},{"id":"t4","speaker":"hero","text":"— {имя}. Это я.\nЯ сказал это в темноту прихожей — чтобы хоть кто-нибудь в этом городе знал, как меня зовут."},{"id":"t5","text":"В коридоре горел бабушкин ночник: гриб со стеклянной шляпкой. Он не мог гореть. Я сам выключил пробки на лестничной клетке."},{"id":"t6","text":"А потом из кухни сказали «ой». Не бабушкиным голосом."},{"id":"t7","speaker":"hero","text":"— Есть кто живой?"},{"id":"t8","text":"На кухне сидели шестеро. У одной на плече был лук. У другой — белая маска с нарисованными глазами. Третья держала нож так, будто нож был единственной вещью в комнате, имеющей смысл."},{"id":"t9","text":"Стол был накрыт: чайник, шесть кружек, открытая банка бабушкиного варенья из ранеток. Варенье было позапрошлогоднее. Я узнал наклейку."},{"id":"t10","speaker":"gwen","text":"— Мы не воры. Мы... появились."},{"id":"t11","speaker":"mikasa","text":"— Он без оружия. Пока."},{"id":"t12","speaker":"annie","text":"— У него ключи. Значит, квартира его. Значит, это мы в гостях. Это хуже."},{"id":"t13","speaker":"felicia","text":"— Ребят. Я, кажется, только что упала с крыши. А теперь сижу тут. С вареньем."},{"id":"t14","speaker":"sakura","text":"— Ты тоже? Я держала кунай... а потом — чайник. И вот."},{"id":"t15","speaker":"tenten","text":"— У меня в руке что-то было. Было — и нет. — Она разжала ладонь. На ладони остался след верёвки."}]},{"id":"sc_night","name":"Шесть кружек","cast":[],"steps":[{"id":"t1","text":"Мы просидели до трёх. Чайник вскипал пять раз. Кто-то вытирал стол, хотя стол был сухой."},{"id":"t2","speaker":"hero","text":"— Так. По одному. Кто вы и откуда?"},{"id":"t3","speaker":"gwen","text":"— Гвен. Гвен Стейси. Бруклин, если это вам о чём-то говорит."},{"id":"t3n","text":"Не говорил."},{"id":"t4","speaker":"sakura","text":"— Сакура. Коноха. Ниндзя, медик, повар в конце концов."},{"id":"t5","speaker":"mikasa","text":"— Микаса Аккерман. Разведкорпус."},{"id":"t6","speaker":"tenten","text":"— Тентен. Тоже ниндзя. Специализация — оружие. Обычно при мне был склад. Сейчас склада нет."},{"id":"t7","speaker":"annie","text":"— Энни Леонхарт. Военная полиция. И да, я знаю, как это звучит."},{"id":"t8","speaker":"felicia","text":"— Фелиция Харди. Не спрашивай."},{"id":"x1","speaker":"gwen","text":"— Стоп. — Гвен подняла руку. — Почему я вас понимаю?\n— В смысле?\n— Я говорю по-английски. — Она сказала это медленно, раздельно. — Вот так. Я говорю по-английски."},{"id":"x2","text":"Она говорила по-английски. Я слышал русский — свой, тюменский, с проглаженными окончаниями."},{"id":"x3n","text":"Сакура сказала что-то короткое и гортанное. Я услышал «горячее». Тентен выругалась — я услышал «чтоб тебя». Микаса произнесла два слова, и все замолчали."},{"id":"x3","speaker":"mikasa","text":"— Шов переводит. С опозданием в полсекунды. Поэтому кажется, что все говорят с акцентом."},{"id":"x4","speaker":"tenten","text":"— Удобно.\n— Страшно, — сказала Фелиция.\n— Не спорю."},{"id":"t9","text":"Все они были здесь не потому, что шли сюда. Каждая попала в ту секунду, когда за спиной уже не осталось варианта «обойдётся». Гвен — стена. Сакура — клинок, который не успела отбить. Микаса и Энни — поле, где обе были последней целью друг друга. Тентен — обстрел. Фелиция — край крыши и очень честный ветер."},{"id":"t10","speaker":"hero","text":"— И все — в мою кухню. В один вечер. В Тюмень."},{"id":"t11","text":"Блокнот лежал в нижнем ящике буфета. Бабушкин: рецепты, погода, «купить соль». На середине рецепты кончились."},{"id":"t12","text":"«Пересылка не стоит на месте. Пересылка стоит на человеке».\n«Пока вахта не принята, шов не закроется и никто не уйдёт домой».\n«Вахту принимают не у двери. Вахту принимают, когда есть кого оставить»."},{"id":"t13","speaker":"hero","text":"— Бабушка была смотрительницей. Квартира — не квартира. Это пересылка. Место, куда попадают те, кто оказался между."},{"id":"t14","speaker":"gwen","text":"— И она... следила?\n— Сорок лет. Каждую ночь."},{"id":"t15","speaker":"annie","text":"— А потом умерла. И шов открылся.\nЯ не сказал «да». Это и без меня сказали."},{"id":"t16","speaker":"mikasa","text":"— Тогда примите вахту. И закройте."},{"id":"t17","text":"Я положил ладонь на дверной косяк и сказал вслух то, что было написано мелким почерком. Дом промолчал. Не отказал — именно промолчал, как человек, который ждёт, когда ты сам поймёшь."},{"id":"t18","speaker":"hero","text":"— Не принимает."},{"id":"t19","speaker":"sakura","text":"— Значит, сначала надо, чтобы у тебя кто-то был. — Она сказала это просто. Как про суп, которому не хватает соли."},{"id":"t20","speaker":"felicia","text":"— Отлично. Шесть девушек, одна кухня. Шансы есть."},{"id":"t21","speaker":"hero","text":"— И шесть зубных щёток.\n— Восемь. Две запасные.\n— Откуда?!\nНикто не ответил. В Тюмени вообще редко отвечают на такие вопросы."}]},{"id":"sc_morning","name":"Один холодильник","cast":[],"steps":[{"id":"t1","text":"Спали как получилось. Микаса — на полу у двери, лицом к выходу. Энни — рядом, спиной к ней. Сакура — на табуретках у плиты. Гвен — на шкафу. Фелиция — на балконе, в бабушкином пуховике. Тентен — под столом, закутавшись в скатерть."},{"id":"t2","text":"Утром выяснилось: у меня один холодильник, одна ванная и шесть девушек, которые не знают, что такое очередь."},{"id":"t3","speaker":"gwen","text":"— У тебя есть кофе?"},{"id":"t4","speaker":"hero","text":"— У меня есть всё, что было у бабушки."},{"id":"t5","speaker":"gwen","text":"— Это не ответ. Это диагноз."},{"id":"t6","text":"Пельмени кончились в девять. Хлеб — в половине десятого. К одиннадцати на кухне варили то, что нашлось: три картошки, половина луковицы и уверенность Сакуры, что из этого можно сделать съедобное. Получилось."},{"id":"t7","speaker":"mikasa","text":"— Нам нужен хлеб.\n— И молоко.\n— И что-нибудь, чем можно резать."},{"id":"t8","text":"Микаса и Энни ушли в магазин. Вернулись через сорок минут — с хлебом, молоком, двумя луковицами и одним чужим пакетом."},{"id":"t9","speaker":"hero","text":"— А пакет чей?"},{"id":"t10","speaker":"annie","text":"— Водителя маршрутки. Он открыл двери прежде, чем мы попросили.\n— Вы угнали маршрутку?\n— Нет. Он просто остановился."},{"id":"t11","speaker":"mikasa","text":"— Я заплатила. Он дал сдачу и сказал: «девочки, аккуратнее».\n— И это всё?\n— И мы забрали пакет. Он лежал на сиденье."},{"id":"t12","text":"Пакет мы отнесли обратно на остановку. Водитель сказал: «Бывает». В Тюмени вообще редко спорят с очевидным."},{"id":"t13","speaker":"sakura","text":"— Ешь.\n— Что это?\n— Не спрашивай. Ешь."},{"id":"t14","text":"Я съел. И готов был отдать за добавкой квартиру, ключи и всё, что было у бабушки."},{"id":"t15","speaker":"felicia","text":"— Слушай. Я нашла в прихожей квитанцию. Из ломбарда. Бабушкину?\n— Бабушкину. Часы в залоге. Я их не выкупил."},{"id":"t16","speaker":"felicia","text":"— Их ещё можно выкупить.\n— И зачем тебе?\n— Не мне. Просто не люблю, когда вещи лежат не у своих."},{"id":"t17","speaker":"gwen","text":"— Мы это чувствуем. Каждой из нас нужно вернуться к своему месту. Не домой — к месту, где нас застало. Оно есть в этом городе. Все шесть."},{"id":"t18","text":"Она объяснила так, будто читала вслух: у шва есть узелки. Каждой нужен свой узелок здесь — чтобы шов отпустил её там. Пока она не пройдёт его, она никуда не уйдёт. И шов не закроется. Никогда."},{"id":"t19","speaker":"tenten","text":"— А когда пройдём — уйдём?\n— Когда пройдёте — сможете. Уйти или остаться. Это уже не шов решает."},{"id":"t20","speaker":"hero","text":"— Шесть порогов. И вахта."},{"id":"t21","speaker":"mikasa","text":"— И один ты. Плохая математика."},{"id":"t22","text":"Я достал карту. Тюмень маленькая, если считать по мостам, и очень большая, если считать по людям."}]},{"id":"sc_bathroom","name":"Очередь в ванную","cast":[],"steps":[{"id":"t1","text":"Семь утра. Одна ванная, шесть девушек и батарея, которая стучит, как сосед сверху, только честнее."},{"id":"t2","text":"К четвёртому дню у зеркала висело расписание. Первое сорвали в споре, который никто не выиграл. Второе написали от руки и подписали."},{"id":"t3","speaker":"gwen","text":"— Окей. Объясните мне, почему у вас горячая вода идёт прямо из стены?\n— Из котельной. По трубам.\n— У нас так не умеют. — Она потрогала трубу и не убрала руку. — Это лучшее, что я здесь видела."},{"id":"t4","speaker":"sakura","text":"— Можно я попробую? — Она приложила ладонь к трубе и нахмурилась. — Чувствую... и не чувствую. Как будто рука в варежке."},{"id":"t5","speaker":"tenten","text":"— Потому что здесь нет чакры. — Тентен сидела на стиральной машине с гаечным ключом. — Я проверила. Три раза."},{"id":"t6","text":"Из смесителя торчала разобранная внутренность. Тентен собирала её с лицом человека, который наконец нашёл, чем заняться."},{"id":"t7","speaker":"tenten","text":"— Всё. Теперь не течёт.\n— А вода?\n— Вода — это ваша часть."},{"id":"t8","text":"Вода пошла. Тентен посмотрела на неё почти с уважением и вытерла руки о штаны."},{"id":"t9","text":"В дверь ванной стучали. Энни зашла туда сорок минут назад и не выходила."},{"id":"t10","speaker":"mikasa","text":"— Энни. Выходи.\n— Нет.\n— Ты не в бою.\n— Именно поэтому."},{"id":"t11","text":"Она вышла через минуту — с мокрыми волосами и совершенно невозмутимым лицом. В ванне была набрана горячая вода, и в ней плавала одна перчатка."},{"id":"t12","speaker":"annie","text":"— Я просто сидела. — Она не извинялась. — Там тепло. У меня давно не было тепло."},{"id":"t13","text":"Микаса смотрела на неё долго. Потом сказала:"},{"id":"t14","speaker":"mikasa","text":"— Я следующая. И я тоже буду сидеть.\nПауза.\n— Долго."},{"id":"t15","text":"Так появилось первое правило дома: в ванной можно сидеть сколько хочешь, но если стучат три раза — выходи."},{"id":"t16","text":"Второе правило появилось из-за балкона. Кто-то пытался выйти через него на улицу. Кто-то — это Фелиция."},{"id":"t16b","text":"Я поймал её за локоть."},{"id":"t17","speaker":"felicia","text":"— Пятый этаж. — Она не сопротивлялась. — Проверяла. У вас тут ветер другой. И карниз скользкий. И вообще, я не ухожу, тигр."},{"id":"t18","text":"— А зачем тогда?\n— Я всегда проверяю, где выход, — сказала она, будто это было очевидно. — Привычка. Не обижайся."},{"id":"t19","text":"Гвен тем временем пыталась повесить на окно штору — и не могла. Между пальцами у неё не было ничего."},{"id":"t20","speaker":"gwen","text":"— Раньше я делала это за секунду.\n— И сейчас можешь. — Я подал ей гвоздь. — Только руками.\n— Это оскорбительно.\n— Это Тюмень."},{"id":"t21","text":"Она засмеялась, взяла гвоздь и прибила штору криво. Потом постучала костяшками по стиральной машине — раз, два, три, четыре — и остановилась."},{"id":"t21b","speaker":"gwen","text":"— Привычка. Я так проверяю, что мир ещё держит ритм."},{"id":"t22","text":"К вечеру в стакане у зеркала стояло восемь зубных щёток. Никто не признался, откуда две запасные."},{"id":"t23","text":"И ещё одно: в квартире стало пахнуть не бабушкой, а людьми. Я не знал, хорошо это или плохо. Просто заметил."}]},{"id":"sc_shop","name":"Монетка","cast":[],"steps":[{"id":"t1","text":"На третий день деньги на еду кончились раньше, чем октябрь. Я посчитал: четыре тысячи до аванса и шесть человек, которые никогда ничего не покупали."},{"id":"t2","speaker":"hero","text":"— Идём в магазин. Все.\n— Зачем все?\n— Чтобы вы видели, как это работает."},{"id":"t3","text":"«Монетка» на углу встретила нас холодным светом, запахом мокрого картона и очередью из четырёх человек."},{"id":"t4","speaker":"sakura","text":"— У вас всё в других числах. — Она читала ценники, шевеля губами. — Это дорого?\n— Это нормально.\n— А это?\n— Это мы не берём."},{"id":"t5","text":"Она набрала муки, яиц, лука и курицу и понесла это к тележке так, будто несла раненого."},{"id":"t6","speaker":"tenten","text":"— Зачем три вида соли?\n— Для разного.\n— Это соль.\n— Это Тюмень. — Я сам не знал, что это значит, но звучало убедительно."},{"id":"t7","text":"Тентен остановилась у полки с рисом, взяла пакет и на секунду зажмурилась. Пакет остался пакетом."},{"id":"t8","speaker":"tenten","text":"— Не открывается. — Она поставила его обратно, ровно, как на полке. — Раньше бы в свиток ушёл. И место бы ещё осталось."},{"id":"t9","text":"Энни стояла у молочного ряда и держала йогурт, изучая дату на крышке, как донесение."},{"id":"t10","speaker":"annie","text":"— У вас молоко с датой.\n— Чтобы знать, когда испортится.\n— У нас молоко было молоком. — Она поставила один стакан в тележку. Потом второй. — Три. Не спрашивай."},{"id":"t11","text":"Микаса шла за тележкой, как охрана: спина прямая, глаза по сторонам, короткая остановка у выхода."},{"id":"t12","speaker":"mikasa","text":"— Там охранник.\n— Он смотрит, чтобы не воровали.\n— Я не ворую.\n— Я знаю. Он не знает."},{"id":"t13","text":"У полки с ножами она задержалась. Взяла дешёвый, взвесила в руке, посмотрела на цену и поставила обратно — аккуратно, будто извиняясь."},{"id":"t14","speaker":"hero","text":"— Нравится?\n— Нет. Он плохой.\nПауза.\n— У тебя на кухне хуже."},{"id":"t15","text":"Фелиция шла рядом со мной и вдруг исчезла. Я нашёл её у стойки с шоколадом: руки в карманах, взгляд в потолок, крайне занятой человек."},{"id":"t16","speaker":"hero","text":"— Ты собиралась?\n— Я всегда собираюсь. — Она не улыбалась. — Это не значит, что делаю."},{"id":"t17","speaker":"felicia","text":"— Тут камеры.\n— Знаю. — Она кивнула на объектив, будто здороваясь. — У вас их больше, чем людей. Отвратительно."},{"id":"t18","text":"На кассе пожилая женщина посмотрела на тележку, потом на меня, потом на девушек."},{"id":"t19","text":"— Корми их, — сказала она. — Худые.\n— Кормлю.\n— Плохо кормишь."},{"id":"t20","text":"Гвен всю очередь болтала с ней: про погоду, про цены, про то, что в Бруклине тоже холодно, только ветер злее. Я не знал, что она так умеет."},{"id":"t21","text":"Обратно ехали на маршрутке. Микаса стояла, держась за поручень. Энни села через проход — не рядом."},{"id":"t22","speaker":"tenten","text":"— А зачем кнопка «стоп»?\n— Чтобы остановиться там, где надо.\n— У нас останавливались, где скажут. — Она нажала. — Мне нравится."},{"id":"t23","text":"Водитель остановился на полквартала раньше и ничего не сказал. Мы вышли. Тентен шла довольная, Энни — нет."},{"id":"t24","text":"Чек был длинный, как список долгов. Дома мы разложили пакеты на столе, и впервые за три дня я почувствовал, что это не катастрофа, а просто очень тесная жизнь."}]},{"id":"sc_evening","name":"Первый вечер","cast":[],"steps":[{"id":"t1","text":"Вечером включили бабушкин телевизор — тот, который надо стукнуть по корпусу, чтобы появилась картинка."},{"id":"t2","text":"Показывали новости Тюмени: ремонт дороги, лёд на Туре, цена на бензин. Девушки смотрели так, как смотрят на чужую планету."},{"id":"t3","speaker":"gwen","text":"— И это всё?\n— Это новости.\n— У вас тут настолько спокойно, что показывают дорогу?"},{"id":"t4","text":"Микаса сидела в кресле у двери, не снимая куртку. Энни — на подоконнике, колени к груди. Сакура заснула первой: у стола, на стуле, с половником в руке."},{"id":"t5","speaker":"annie","text":"— Можно вопрос? — Она не спала. — Почему мы?\nНикто не ответил. В блокноте ответа тоже не было."},{"id":"t6","speaker":"sakura","text":"— Потому что в тот момент каждая из нас думала одно и то же.\n— И что?\n— «Пусть кто-нибудь заметит»."},{"id":"t7","text":"Стало тихо. В батарее что-то щёлкнуло."},{"id":"t8","speaker":"gwen","text":"— Я думала: «Ну вот, сейчас кто-нибудь поймает».\n— А мне пришло в голову «наконец-то», — сказала Фелиция. — Не берите в голову, тигр."},{"id":"t9","text":"Энни засмеялась первой — коротко, некрасиво, будто вырвалось. Потом Тентен. Потом все. Мы смеялись над этим дольше, чем было прилично."},{"id":"t10","text":"Потом делили места. Диван — Сакуре и Гвен. Матрас на полу — Микасе и Энни, но каждая легла с краю. Тентен забралась под стол. Фелиция вышла на балкон."},{"id":"t11","text":"— Там холодно.\n— Я спала в холоднее.\n— Это Тюмень. У нас холодно по-настоящему.\n— Тогда я возьму пуховик. — Она сняла с вешалки бабушкин."},{"id":"t12","text":"— Свет гасить? — спросил я.\n— Не надо, — сказала Сакура из-под пледа. — Можно, мы первый раз поспим при свете?"},{"id":"t13","text":"Никто не стал смеяться. Я выключил верхний свет и оставил ночник-гриб."},{"id":"t14","speaker":"mikasa","text":"— Я буду у двери.\n— Тут не от кого защищаться.\n— Я знаю. — Она поправила куртку. — Это не для защиты."},{"id":"t15","speaker":"annie","text":"— Тогда я у окна.\n— Ты весь день у окна.\n— А теперь ночь. — Она посмотрела на меня. — Если что-то войдёт сверху, я успею."},{"id":"t16","text":"Они говорили об этом спокойно, как об уборке. Двое солдат охраняли чужую кухню от того, чего в этом городе не было."},{"id":"n1","text":"В дверь позвонили. В десять вечера, без предупреждения — так в этом доме делала только соседка с четвёртого."},{"id":"n2","text":"— Баба Валя.\n— Здравствуй, — сказала она и посмотрела мимо меня в коридор, где стояли шесть пар обуви. — Я думала, ты один приехал."},{"id":"n3","speaker":"hero","text":"— Я не один."},{"id":"n4","text":"Она посмотрела ещё раз: на Энни в проёме, на Микасу за её спиной, на Тентен, которая держала разобранный смеситель."},{"id":"n5","speaker":"hero","text":"— Это... родственницы.\n— Шесть?\n— С разных сторон."},{"id":"n6","text":"Она помолчала. Потом достала из кармана связку и отдала мне второй ключ — от подъезда. Домофон у нас не работает с прошлого года.\n— Корми их, — сказала она уже с лестницы. — Худые."},{"id":"n7","text":"Так в квартире появился седьмой ключ. И первая версия, которую знал весь подъезд: к бабушкиному внуку приехали родственницы."},{"id":"t17","text":"Я зашёл в свою комнату и включил свет. Тут всё было бабушкино: её чашка, её календарь, последняя запись в блокноте — «купить соль»."},{"id":"t18","speaker":"hero","text":"— Соль, — сказал я вслух. — Ладно. Завтра купим соль."},{"id":"t19","text":"В квартире за стеной кто-то ходил. На кухне тихо спорили, чей стакан. В коридоре горел гриб."},{"id":"t20","text":"Я подумал: наверное, это и есть пересылка — не мистика и не шов. Просто дом, где какое-то время живут те, кому больше некуда."},{"id":"t21","text":"И ещё подумал: если вахту принимают, когда есть кого оставить, то у меня теперь есть шесть человек, которых нельзя оставлять."}]},{"id":"sc_shift","name":"Смена","cast":[],"steps":[{"id":"t1","text":"В понедельник мне всё-таки надо было на работу. Я сказал это за завтраком и почувствовал себя предателем."},{"id":"t2","speaker":"hero","text":"— Я вернусь в семь. Не сжигайте дом."},{"id":"t3","speaker":"annie","text":"— А если что-то войдёт в дом?\n— В Тюмень?\n— В дом."},{"id":"t4","text":"Микаса встала и подошла к двери. Энни встала за ней. Они не сговаривались."},{"id":"t5","speaker":"mikasa","text":"— Мы справимся.\n— Я в этом не сомневался.\n— Иди."},{"id":"t6","text":"Работа была обычная: склад, накладные, чай в пластиковом стакане. Восемь часов я думал о квартире, в которой шесть человек, не знающих, как работает домофон."},{"id":"t7","text":"В обед позвонила соседка. Я не давал ей номер.\n— {имя}, — сказала она. — У тебя там что, ремонт?\n— Что-то вроде."},{"id":"t8","text":"Я вернулся в семь. В квартире пахло едой, а не бедой."},{"id":"t9","text":"Тентен починила кран и выключатель в коридоре. Сакура сварила борщ из того, что нашла. Микаса вымыла окна. Энни, кажется, спала — впервые за всё время как следует."},{"id":"t10","speaker":"gwen","text":"— Что такое «аванс»? — спросила Гвен с порога.\n— Это когда деньги дают раньше.\n— А «зарплата»?\n— Это когда позже."},{"id":"t11","text":"На столе стояла банка варенья и записка бабы Вали: «Дети, не шумите после одиннадцати». Почерк был крупный, как у учительницы."},{"id":"t12","speaker":"felicia","text":"— Мы не шумели.\n— Ты уронила табуретку.\n— Это был не шум. Это была музыка."},{"id":"t13","text":"Я сел на табуретку и понял, что за восемь часов впервые за неделю не думал о шве. Просто работал."},{"id":"t14","text":"И ещё понял: пока я хожу на работу, кто-то дома ждёт. Это оказалось очень простым и очень тяжёлым чувством."}]},{"id":"sc_hub","name":"Вахта","card":false,"cast":[],"steps":[{"id":"t1","text":"Дни пошли. В квартире появилось расписание, кто моет посуду. Оно не соблюдалось, но висело."},{"id":"t2","if":"вахта == 0","text":"Утром все смотрели на меня и ждали. Я смотрел на карту и ждал, что кто-нибудь скажет первым."},{"id":"t3","if":"вахта == 1","text":"Первый порог остался позади. Квартира стала тише — и как будто теснее, хотя никто никуда не съезжал."},{"id":"t4","if":"вахта >= 3","text":"К третьему порогу квартира пахла уже не бабушкой, а нами: чужим мылом, вареньем и чем-то горелым."},{"id":"t5","if":"вахта >= 5","text":"Оставался последний узелок. Все это знали — и все делали вид, что нет."},{"id":"d1","if":"вахта == 2","text":"На третий порог шли пешком: Тентен объяснила, что «ваш транспорт» едет не туда, куда написано, а туда, куда едет."},{"id":"d2","if":"вахта == 4","text":"Микаса подняла холодильник, чтобы вымыть под ним. Я не спрашивал. Энни сказала «обычное дело» и вытерла пол."},{"id":"d3","if":"вахта >= 5","text":"Сакура готовила на шесть человек и на соседа. Сосед не приходил, но кастрюлю вернул — чистую."},{"id":"t6","choices":[{"if":"порог_микаса == false","text":"Стена на берегу — Микаса","goto":"sc_mikasa:t1"},{"if":"порог_гвен == false","text":"Крыша и мост — Гвен","goto":"sc_gwen:t1"},{"if":"порог_тентен == false","text":"Старый цех — Тентен","goto":"sc_tenten:t1"},{"if":"порог_энни == false","text":"Лёд на катке — Энни","goto":"sc_annie:t1"},{"if":"порог_сакура == false","text":"Верхний Бор, костёр — Сакура","goto":"sc_sakura:t1"},{"if":"порог_фелиция == false","text":"Ночные крыши и ломбард — Фелиция","goto":"sc_felicia:t1"},{"if":"порог_микаса and порог_гвен and порог_тентен and порог_энни and порог_сакура and порог_фелиция","text":"Шесть узелков затянуты. Пора на набережную.","goto":"sc_finale:t1"}]}]},{"id":"sc_mikasa","name":"Стена","cast":[],"steps":[{"id":"t1","text":"Острог стоял на берегу: четыре бревна, вросшие в склон, и табличка. Микаса остановилась за десять шагов и дальше не пошла."},{"id":"t2","speaker":"mikasa","text":"— Стена."},{"id":"t3","speaker":"hero","text":"— Здесь нечего защищать. Это музей.\n— Я знаю."},{"id":"t4","text":"Она смотрела на брёвна так, как смотрят на человека, которого давно не видели."},{"id":"t5","speaker":"mikasa","text":"— Тогда, у стены, я перестала быть нужна. Всё, что я умела, стало бесполезно в ту секунду, когда стена перестала быть последней."},{"id":"t6","speaker":"hero","text":"— А теперь?"},{"id":"t7","speaker":"mikasa","text":"— Теперь у меня нет шарфа. — Она коснулась шеи. — Он был тёплый. Пах дымом. Здесь шарфа нет."},{"id":"t8","text":"Воздух между ней и брёвнами стоял неправильно: как над горячим асфальтом, только тихо."},{"id":"c1","choices":[{"text":"Подойти и встать рядом, плечом к плечу","goto":"sc_mikasa:a1"},{"text":"Отойти на шаг и дать ей пройти самой","goto":"sc_mikasa:b1n"}]},{"id":"a1","set":[{"var":"близость_микаса","op":"add","value":"2"}],"speaker":"mikasa","goto":"sc_mikasa:t9","text":"— Ты стоишь неправильно.\n— Как?\n— Ближе.\nОна подвинулась сама, и её плечо оказалось у моего."},{"id":"b1n","text":"Она прошла одна. Приложила ладонь к брёвнам, постояла. Потом вернулась."},{"id":"b1","set":[{"var":"близость_микаса","op":"add","value":"1"}],"speaker":"mikasa","goto":"sc_mikasa:t9","text":"— Стену не обойти, если не к кому возвращаться."},{"id":"t9","set":[{"var":"порог_микаса","op":"set","value":"true"},{"var":"вахта","op":"add","value":"1"}],"text":"Ладонь на бревне. Что-то в воздухе отпустило — будто выдохнули. Она стояла так долго, что я замёрз."},{"id":"t10","speaker":"mikasa","text":"— Холодная. Настоящая. — Она убрала руку. — Спасибо, что не сказал «пойдём отсюда»."},{"id":"t11","text":"На обратном пути она шла на полшага позади — так, чтобы я не видел, что она улыбается. Я видел.","goto":"sc_hub:t1"}]},{"id":"sc_gwen","name":"Двадцать третий этаж","cast":[],"steps":[{"id":"t1","text":"Крыша была двадцать третья и очень честная: ветер здесь не притворялся ласковым."},{"id":"t2","speaker":"gwen","text":"— Отсюда видно мост. — Она стояла у самого края. — Тот, на котором люди вешают замки."},{"id":"t3","speaker":"gwen","text":"— В моём мире я упала. — Она сказала это в ветер, будто не мне. — И меня поймали. Здесь никто не поймает. Здесь просто нет никого, кто умеет."},{"id":"t4","speaker":"hero","text":"— Я умею держать."},{"id":"t5","speaker":"gwen","text":"— Не в этом дело. — Она наконец посмотрела. — В этом и дело. Но не только."},{"id":"t6","text":"Паутина между её пальцами была видна только на свету: тонкие белые нити, которые она всё время сматывала, будто они могли что-то выдать."},{"id":"t7","speaker":"gwen","text":"— Если я останусь, они исчезнут. Совсем. Я перестану быть той, кто ловит падающих.\n— А если вернёшься?\n— Тогда я снова буду она. И снова буду одна."},{"id":"t8","text":"Внизу Тюмень складывалась в квадраты: дворы, гаражи, оранжевые крыши. Обычный город. Очень занятой тем, чтобы не смотреть вверх."},{"id":"c1","choices":[{"text":"Взять её за руку и шагнуть к краю вместе","goto":"sc_gwen:a1"},{"text":"Остаться в двух шагах и просто быть здесь","goto":"sc_gwen:b1"}]},{"id":"a1","set":[{"var":"близость_гвен","op":"add","value":"2"}],"speaker":"gwen","goto":"sc_gwen:t9","text":"— Ты с ума сошёл.\nОна не отпустила руку.\n— Мы оба с ума сошли.\n— Да.\nВетер был сильнее. Она держалась."},{"id":"b1","set":[{"var":"близость_гвен","op":"add","value":"1"}],"speaker":"gwen","goto":"sc_gwen:t9","text":"— Ты не подошёл.\n— Не подошёл.\n— Спасибо. Если бы подошёл, мне пришлось бы решать быстрее, чем я готова."},{"id":"t9","set":[{"var":"порог_гвен","op":"set","value":"true"},{"var":"вахта","op":"add","value":"1"}],"text":"Она сделала шаг — не вниз, по краю, вдоль. И там, где кончался парапет, воздух стал плотным, как вода. Она прошла по нему и вернулась. Узелок затянулся."},{"id":"t10","speaker":"gwen","text":"— Знаешь, что самое страшное? Не упасть.\n— Что?\n— Прыгнуть и не узнать, поймают ли."},{"id":"t11","speaker":"gwen","text":"— А на мосту этом правда вешают замки?\n— Вешают.\n— И что потом?\n— Потом ключ бросают в Туру.\n— Варвары."},{"id":"t12","text":"С крыши мы спустились пешком: лифт, сказала она, слишком медленный для людей, которые только что ходили по воздуху. Ключ от бабушкиной квартиры я не бросил. Но в кармане он стал тяжелее.","goto":"sc_hub:t1"}]},{"id":"sc_tenten","name":"Цех","cast":[],"steps":[{"id":"t1","text":"Старый цех за путями никто не охранял: ворота приоткрыты, внутри пахло маслом, пылью и железом, которое ещё помнит, что его грели."},{"id":"t2","speaker":"tenten","text":"— Вот это — кузня. — Она сказала это почти нежно. — В моём мире у меня был свиток. Один. Я его не успела раскрыть."},{"id":"t3","speaker":"hero","text":"— Что в нём было?"},{"id":"t4","speaker":"tenten","text":"— Всё. Склад оружия в одном свитке. Удобно, пока свиток есть."},{"id":"t5","text":"Она нашла горн, потрогала, нашла молоток, взвесила в руке и поморщилась, будто молоток был не того веса и не того города."},{"id":"t6","speaker":"tenten","text":"— У вас тут что, всё руками?\n— В основном.\n— Тогда ладно. Руки у меня тоже есть."},{"id":"t7","text":"Полчаса она грела, стучала, шипела в воду, ругалась на двух языках. Потом положила на верстак что-то маленькое и горячее."},{"id":"t8","speaker":"tenten","text":"— Ключ.\n— Второй?\n— Второй.\n— Зачем?\n— Дом не должен закрываться на один ключ. Особенно такой дом."},{"id":"t9","text":"Ключ был грубый, прямо с молотка, но он подошёл. Замок в бабушкиной двери щёлкнул с первого раза — так, как не щёлкал сорок лет."},{"id":"c1","choices":[{"text":"Сказать, что это лучший ключ в моей жизни","goto":"sc_tenten:a1"},{"text":"Молча повесить его на гвоздь рядом с бабушкиным","goto":"sc_tenten:b1n"}]},{"id":"a1","set":[{"var":"близость_тентен","op":"add","value":"2"}],"speaker":"tenten","goto":"sc_tenten:t10","text":"— Лучший?\n— Лучший.\n— Он кривой.\n— Он открывает.\n— Это не одно и то же.\n— В моей жизни — одно."},{"id":"b1n","text":"Она посмотрела на гвоздь, потом на меня."},{"id":"b1","set":[{"var":"близость_тентен","op":"add","value":"1"}],"speaker":"tenten","goto":"sc_tenten:t10","text":"— Ты его не в карман.\n— В карман его возьмут другие.\n— Правильно. Пусть висит."},{"id":"t10","set":[{"var":"порог_тентен","op":"set","value":"true"},{"var":"вахта","op":"add","value":"1"}],"text":"Уходя, она оглянулась на горн. Воздух над ним дрогнул и выровнялся — будто кто-то невидимый закрыл за нами дверь."},{"id":"t11","speaker":"tenten","text":"— Слушай. Если я останусь, свиток не вернётся. Я перестану доставать из воздуха мечи.\n— И что тогда?\n— Тогда у меня останутся руки. И, может, это и есть самое страшное."},{"id":"t12","text":"Она засмеялась первой. Я — следом, с опозданием, как всегда.","goto":"sc_hub:t1"}]},{"id":"sc_annie","name":"Лёд","cast":[],"steps":[{"id":"t1","text":"Каток закрыли ещё в девять, но лёд в нём не растаял: старый холодильник под бетоном работал, потому что его никто не выключил. Как всё в этом городе."},{"id":"t2","speaker":"annie","text":"— Я стояла на льду. — Она сказала это, глядя на каток сверху, с трибуны. — Не каталась. Стояла. И ждала."},{"id":"t3","speaker":"hero","text":"— Кого?"},{"id":"t4","speaker":"annie","text":"— Не кого. Когда. Когда всё решится без меня, чтобы мне не пришлось."},{"id":"t5","text":"Она спустилась по ступенькам медленно, ровно, как человек, который всю жизнь ходил по тонкому. Конёк под ногой был один и не её размера."},{"id":"t6","speaker":"annie","text":"— В моём мире я умею становиться твёрдой. Не смелой — твёрдой. Каменной. Люди думают, это сила. Это просто способ не чувствовать."},{"id":"t7","speaker":"hero","text":"— А здесь?"},{"id":"t8","speaker":"annie","text":"— Здесь лёд. Он не спросит, готова ли я."},{"id":"t9","text":"Она вышла на середину и встала. Потом начала — и это не было катание. Это было очень медленное, очень точное движение по кругу, где каждый шаг слышно."},{"id":"c1","choices":[{"text":"Выйти на лёд и подать руку","goto":"sc_annie:a1"},{"text":"Стоять у борта, чтобы она видела: я никуда не ушёл","goto":"sc_annie:b1n"}]},{"id":"a1","set":[{"var":"близость_энни","op":"add","value":"2"}],"speaker":"annie","goto":"sc_annie:t10","text":"— Я не просила.\n— Знаю.\nОна взяла.\n— Только не тяни. Я сама."},{"id":"b1n","text":"Она доехала до борта и остановилась рядом."},{"id":"b1","set":[{"var":"близость_энни","op":"add","value":"1"}],"speaker":"annie","goto":"sc_annie:t10","text":"— Ты стоял.\n— Стоял.\n— Хорошо. Я ненавижу, когда уходят в середине."},{"id":"t10","set":[{"var":"порог_энни","op":"set","value":"true"},{"var":"вахта","op":"add","value":"1"}],"text":"Она сделала ещё круг, и лёд под ней треснул — коротко, будто кто-то щёлкнул пальцами. Трещина прошла до борта и остановилась. Энни вышла. Узелок затянулся."},{"id":"t11","speaker":"annie","text":"— Если я останусь, я перестану становиться твёрдой. Совсем.\n— Это плохо?\n— Это ужасно.\n— И?\n— И, кажется, я этого хочу."},{"id":"t12","text":"Обратно она шла в моих перчатках. Своих у неё не было — она их не носила. В моих было теплее, чем я ожидал.","goto":"sc_hub:t1"}]},{"id":"sc_sakura","name":"Верхний Бор","weather":"snow","cast":[],"steps":[{"id":"t1","text":"Верхний Бор осенью — это сосны, мокрые листья и запах, какого не бывает в городах, где плохо с воздухом. Мы нашли поляну минут за двадцать от парковки."},{"id":"t2","speaker":"sakura","text":"— Дрова нужны сухие. Иначе дым. — Она уже разбирала ветки, будто делала это каждое утро. — В моём мире я так готовила. Между заданиями."},{"id":"t3","speaker":"hero","text":"— И кого кормила?"},{"id":"t4","speaker":"sakura","text":"— Всех. Кто приходил. Наруто съедал три порции и говорил, что мало."},{"id":"t5","text":"Она поставила на огонь котелок, который принесла из квартиры, хотя я говорил, что мы идём гулять."},{"id":"t6","speaker":"sakura","text":"— Слушай. Тогда, с кунаем... я не успела. Не отбила. И не вылечила. Я умею лечить, а руки были заняты."},{"id":"t7","speaker":"hero","text":"— Здесь никого не надо лечить."},{"id":"t8","speaker":"sakura","text":"— Здесь надо кормить. Это почти то же. — Она сказала это, глядя в огонь. — Почти."},{"id":"t9","text":"Из трёх пачек лапши, лука и пакетика чего-то непонятного она сварила такое, что я обжёг язык и не пожалел."},{"id":"c1","choices":[{"text":"Съесть всё и попросить добавки","goto":"sc_sakura:a1"},{"text":"Сказать, что бабушка варила так же, и рассказать про неё","goto":"sc_sakura:b1n"}]},{"id":"a1","set":[{"var":"близость_сакура","op":"add","value":"2"}],"speaker":"sakura","goto":"sc_sakura:t10","text":"— Ты обжёгся.\n— Ага.\n— Значит, вкусно.\nОна засмеялась и подложила ещё."},{"id":"b1n","text":"Она слушала, не перебивая, и мешала лапшу."},{"id":"b1","set":[{"var":"близость_сакура","op":"add","value":"1"}],"speaker":"sakura","goto":"sc_sakura:t10","text":"— Значит, я варю как твоя бабушка.\n— Почти.\n— Это лучшее, что мне говорили за год."},{"id":"t10","set":[{"var":"порог_сакура","op":"set","value":"true"},{"var":"вахта","op":"add","value":"1"}],"text":"Огонь догорел до красных углей. Над ними воздух дрогнул, вытянулся и лёг. Сакура вытерла руки о штаны и посмотрела на меня так, будто впервые за вечер увидела."},{"id":"t11","speaker":"sakura","text":"— Если я останусь, я перестану лечить. Руки станут обычными.\n— Это страшно?\n— Это как если бы у тебя отняли слух.\n— И?\n— И я всё равно останусь варить суп."},{"id":"t12","text":"Котелок она несла обратно сама. Сказала: «Посуду моет тот, кто ел». Я ел больше всех. Я и мыл.","goto":"sc_hub:t1"}]},{"id":"sc_felicia","name":"Крыши и ломбард","cast":[],"steps":[{"id":"t1","text":"Крыши на Республики плоские, тёплые от труб и совершенно бесстыдные: с них видно всё, а тебя — только если очень постараться."},{"id":"t2","speaker":"felicia","text":"— Вот здесь я упала. — Она кивнула вниз, в переулок. — Ну, не здесь. Там. Но ветер такой же."},{"id":"t3","speaker":"hero","text":"— Ты падала и... что?"},{"id":"t4","speaker":"felicia","text":"— И ничего. Я не помню. Помню край, ветер и то, как подумала: «ну вот, сейчас кто-нибудь заметит»."},{"id":"t5","text":"Она шла по парапету, как по тротуару: руки в карманах, плечи расслаблены. Удача была при ней, как чужая сумка, которую забыли вернуть."},{"id":"t6","speaker":"felicia","text":"— Удача — это не суперсила. Это привычка. Пока я воровала, мир делал вид, что не смотрит. Если я останусь здесь, он начнёт смотреть."},{"id":"t7","speaker":"hero","text":"— И что тогда?"},{"id":"t8","speaker":"felicia","text":"— Тогда я буду просто девчонкой, которая умеет открывать чужие окна и ничего за это не получать."},{"id":"t9","text":"Мы спустились вниз, и она потащила меня в ломбард на углу — тот, где витрина помнит ещё девяностые."},{"id":"t10","text":"Квитанция была с собой. Бабушкины часы лежали на подносе, между чужой цепочкой и чужим кольцом: маленькие, с треснувшим стеклом."},{"id":"c1","choices":[{"text":"Выкупить часы и отдать их ей в руки","goto":"sc_felicia:a1"},{"text":"Выкупить часы и сразу надеть на себя","goto":"sc_felicia:b1"}]},{"id":"a1","set":[{"var":"близость_фелиция","op":"add","value":"2"}],"speaker":"felicia","goto":"sc_felicia:t11","text":"— Ты отдаёшь их мне?\n— Тебе.\n— Почему?\n— Потому что ты их нашла."},{"id":"b1","set":[{"var":"близость_фелиция","op":"add","value":"1"}],"speaker":"felicia","goto":"sc_felicia:t11","text":"— Ты их не носишь.\n— Буду.\n— Врёшь.\nОна улыбнулась.\n— Ладно. Носи. Только не потеряй."},{"id":"t11","set":[{"var":"порог_фелиция","op":"set","value":"true"},{"var":"вахта","op":"add","value":"1"}],"text":"На выходе она задержалась у двери и поправила что-то в воздухе — будто нитку. Над переулком воздух дрогнул и лёг ровно. Узелок затянулся."},{"id":"t12","speaker":"felicia","text":"— Знаешь, что самое смешное? Я всю жизнь думала, что мне нужна удача.\n— А оказалось?\n— Оказалось, нужен кто-то, кто подержит дверь, пока я иду. — Она толкнула меня плечом. — Слышишь, тигр?"},{"id":"t13","text":"Часы я отдал ей. Она носила их неправильно — на правой руке, циферблатом внутрь. Как носят чужие секреты.","goto":"sc_hub:t1"}]},{"id":"sc_finale","name":"Набережная","cast":[],"steps":[{"id":"t1","text":"Шов был виден только отсюда: тонкая светлая полоса над Турой, как трещина в стекле, через которое смотрят на город. По воде шёл лёд — мелкий, первый."},{"id":"t2","text":"Шесть узелков были затянуты. В блокноте было написано, что дальше: «Шов берёт одного. Насовсем. Или закрывается сам, если рядом есть кто-то, кто согласится остаться»."},{"id":"t3","speaker":"annie","text":"— То есть кто-то должен сказать «я остаюсь». Вслух."},{"id":"t4","speaker":"mikasa","text":"— И это должно быть правдой. Иначе шов не поверит."},{"id":"t5","speaker":"hero","text":"— А если никто не скажет?"},{"id":"t6","speaker":"mikasa","text":"— Тогда он возьмёт тебя. Ты стоишь ближе всех."},{"id":"t7","speaker":"gwen","text":"— Мы не будем решать за тебя. — Она смотрела на воду. — И ты не решай за нас."},{"id":"t8","text":"Ветер был тот самый, октябрьский: пахнет снегом, но ещё не признаётся. Девчонки стояли полукругом. Кто-то держал кого-то за рукав."},{"id":"c1","choices":[{"if":"близость_микаса >= 2","text":"Взять Микасу за руку и не отпускать","goto":"sc_finale:g_mikasa"},{"if":"близость_гвен >= 2","text":"Взять Гвен за руку и не отпускать","goto":"sc_finale:g_gwen"},{"if":"близость_тентен >= 2","text":"Взять Тентен за руку и не отпускать","goto":"sc_finale:g_tenten"},{"if":"близость_энни >= 2","text":"Взять Энни за руку и не отпускать","goto":"sc_finale:g_annie"},{"if":"близость_сакура >= 2","text":"Взять Сакуру за руку и не отпускать","goto":"sc_finale:g_sakura"},{"if":"близость_фелиция >= 2","text":"Взять Фелицию за руку и не отпускать","goto":"sc_finale:g_felicia"},{"text":"Отойти к перилам и промолчать","goto":"sc_finale:q1"}]},{"id":"g_mikasa","goto":"sc_finale:m3","text":"Я взял её за руку. Ладонь была холодная — она всегда мёрзла первой. Пятеро отошли на шаг, будто по команде, которой никто не давал."},{"id":"m3","speaker":"mikasa","text":"— Я остаюсь. — Она сказала это не громко. Просто и окончательно, как всё, что она говорила. — Здесь стена деревянная. И холодная. И мне не нужно её защищать."},{"id":"m4","text":"Утром шов закрылся. Он закрывался тихо — как закрывают дверь в комнату, где спит ребёнок. Пятеро ушли по одной, и каждая оглядывалась."},{"id":"m5","text":"В своих мирах их больше не помнят. Так шов и работает: он забирает не только человека, но и место, где тот был. Помню только я.\nУтром на спинке стула висел шарф — тот самый, которого здесь не было. Шерсть больше не пахла дымом, только стиркой и домом. Она надела его всё равно."},{"id":"m6","end":true,"endTitle":"ОСТАЁТСЯ МИКАСА","text":"Стена на берегу никуда не денется. Микаса ходит мимо неё и не оборачивается. Иногда — оборачивается."},{"id":"g_gwen","goto":"sc_finale:w3","text":"Я взял её за руку. Пальцы у неё были горячие — она всегда была теплее всех, будто внутри у неё горело что-то, чего она не показывала."},{"id":"w3","speaker":"gwen","text":"— Я остаюсь. — Она выдохнула, будто держала это в себе с самой крыши. — У меня больше нет нитей. Проверила утром: руки пустые, как у всех."},{"id":"w4","text":"Утром шов закрылся. Он закрывался тихо — как закрывают дверь в комнату, где спит ребёнок. Пятеро ушли по одной, и каждая оглядывалась."},{"id":"w5","text":"В своих мирах их больше не помнят. Так шов и работает: он забирает не только человека, но и место, где тот был. Помню только я.\nМы стояли на набережной, пока не замёрзли. Тюмень просыпалась: первый автобус, первый дворник, первый дым из трубы на том берегу."},{"id":"w6","speaker":"gwen","text":"— Будешь держать?\n— Что?\n— Всё. По утрам."},{"id":"w7","end":true,"endTitle":"ОСТАЁТСЯ ГВЕН","text":"Падать она больше не умеет. Держать — умеет. Каждое утро она подаёт мне кружку так, чтобы наши пальцы встречались."},{"id":"g_tenten","goto":"sc_finale:te3","text":"Я взял её за руку. Ладонь была в мелких старых ожогах — карта работы, которую она никогда не показывала."},{"id":"te3","speaker":"tenten","text":"— Я остаюсь. — Она сжала кулак и разжала. — Свиток не открывается с утра. Пусто. Зато в двери два ключа."},{"id":"te4","text":"Утром шов закрылся. Он закрывался тихо — как закрывают дверь в комнату, где спит ребёнок. Пятеро ушли по одной, и каждая оглядывалась."},{"id":"te5","text":"В своих мирах их больше не помнят. Так шов и работает: он забирает не только человека, но и место, где тот был. Помню только я.\nЧерез неделю она выковала третий ключ. Сказала: «на всякий случай». Я не спросил, для кого."},{"id":"te6","end":true,"endTitle":"ОСТАЁТСЯ ТЕНТЕН","text":"Оружия из воздуха она больше не достаёт. Но если в доме что-то сломалось — она уже стоит рядом с молотком."},{"id":"g_annie","goto":"sc_finale:a3","text":"Я взял её за руку — раньше, чем успел подумать. Она не отняла. Только посмотрела так, будто я нарушил правило, о котором никто не договаривался."},{"id":"a3","speaker":"annie","text":"— Я остаюсь. — Она не стала объяснять. Просто сказала — и всё. — Теперь мне не нужно становиться твёрдой, чтобы это выговорить."},{"id":"a4","text":"Утром шов закрылся. Он закрывался тихо — как закрывают дверь в комнату, где спит ребёнок. Пятеро ушли по одной, и каждая оглядывалась."},{"id":"a5","text":"В своих мирах их больше не помнят. Так шов и работает: он забирает не только человека, но и место, где тот был. Помню только я.\nЛёд на катке растаял на следующей неделе — впервые за тридцать лет. Энни сказала, что это совпадение. Сказала так, что я не стал спорить."},{"id":"a6","end":true,"endTitle":"ОСТАЁТСЯ ЭННИ","text":"Каменной она больше не станет, даже если очень попросить. По вечерам она спит у двери — но уже лицом к нам."},{"id":"g_sakura","goto":"sc_finale:s3","text":"Я взял её за руку. Пальцы пахли дымом и лапшой — и она тут же попыталась вытереть их о штаны, будто это было важно."},{"id":"s3","speaker":"sakura","text":"— Я остаюсь. — Она показала палец с пластырем. — Руки обычные. Проверила на порезе.\n— И?\n— И суп варю так же."},{"id":"s4","text":"Утром шов закрылся. Он закрывался тихо — как закрывают дверь в комнату, где спит ребёнок. Пятеро ушли по одной, и каждая оглядывалась."},{"id":"s5","text":"В своих мирах их больше не помнят. Так шов и работает: он забирает не только человека, но и место, где тот был. Помню только я.\nС тех пор в квартире всегда пахнет едой. Это неудобно: я постоянно хочу есть. И очень хорошо: теперь я знаю, зачем возвращаюсь домой."},{"id":"s6","end":true,"endTitle":"ОСТАЁТСЯ САКУРА","text":"Лечить она больше не умеет. Кормить — умеет так, что соседи приходят «просто посмотреть»."},{"id":"g_felicia","goto":"sc_finale:f3","text":"Я взял её за руку. Она вцепилась так, будто мы стояли не на набережной, а на парапете в ветер."},{"id":"f3","speaker":"felicia","text":"— Я остаюсь. И, кажется, у меня началась полоса невезения. — Она показала сломанный ноготь, потерянную перчатку и автобус, ушедший перед носом. — Лучший день в жизни."},{"id":"f4","text":"Утром шов закрылся. Он закрывался тихо — как закрывают дверь в комнату, где спит ребёнок. Пятеро ушли по одной, и каждая оглядывалась."},{"id":"f5","text":"В своих мирах их больше не помнят. Так шов и работает: он забирает не только человека, но и место, где тот был. Помню только я.\nЧасы она носит на правой руке, циферблатом внутрь. Я так и не спросил, почему."},{"id":"f6","end":true,"endTitle":"ОСТАЁТСЯ ФЕЛИЦИЯ","text":"Удача от неё ушла. Дверь, которую надо подержать, она теперь находит сама — и всегда стоит рядом."},{"id":"q1","text":"Я отошёл к перилам и промолчал. Сказать было нечего: шов чувствует ложь, а правды, за которую кто-то согласился бы остаться, у меня не было."},{"id":"q2","text":"Утром девчонки проснулись в своих мирах. Гвен — на стене. Сакура — с кунаем в руке. Микаса и Энни — на поле, обе живые. Тентен — под обстрелом, но уже в укрытии. Фелиция — на краю крыши, но ветер её не забрал."},{"id":"q3","text":"Никто из них не помнил Тюмень. Так шов закрывается: он забирает не только человека, но и место, где тот был. А шов нужно было чем-то закрыть."},{"id":"q4","text":"И тогда он взял меня. Не убил — взял насовсем. В блокноте это называлось «принять вахту»."},{"id":"q5","text":"Квартиры на Мельникайте больше нет на карте: теперь она здесь, где всегда октябрь, где Тура течёт медленно и где я записываю в блокнот рецепты и погоду. Иногда — имена."},{"id":"q6","text":"Иногда шов открывается на одну ночь. Я ставлю чайник и достаю шесть кружек. На всякий случай."},{"id":"q7","end":true,"endTitle":"ОДИН","text":"Шов берёт того, кто стоит ближе всех. Теперь вахту держу я. Если однажды на моей кухне скажут «ой» — я буду готов."}]}],"baseUrl":"stories/tyumen/novels/peresylka/","_builtin":"tyumen/novels/peresylka"}]}]};
